import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { createOrder, getImageUrl } from "../api";

function getErrorFeedback(error) {
  const body = error.body;
  const messages = [];
  const suggestions = [];

  if (Array.isArray(body?.detail)) {
    body.detail.forEach((item) => {
      if (item.msg) {
        messages.push(item.msg);
      }
    });
  } else if (body?.detail) {
    messages.push(String(body.detail));
  }

  const nudges = body?.accessibility?.nudges || [];

  nudges.forEach((nudge) => {
    if (nudge.success_criterion === "3.3.3") {
      if (nudge.message) {
        suggestions.push(nudge.message);
      } else if (nudge.values?.length) {
        suggestions.push(...nudge.values);
      }
    }
  });

  if (!messages.length) {
    messages.push("The order could not be placed.");
  }

  return {
    messages,
    suggestions,
  };
}

function Checkout({ product, quantity }) {
  const navigate = useNavigate();

  const [submitting, setSubmitting] = useState(false);
  const [feedback, setFeedback] = useState(null);

  if (!product) {
    return (
      <div className="page">
        <h1>Checkout</h1>

        <p>No product has been selected.</p>

        <Link className="button" to="/">
          View products
        </Link>
      </div>
    );
  }

  async function handleSubmit(event) {
    event.preventDefault();

    setSubmitting(true);
    setFeedback(null);

    const form = new FormData(event.currentTarget);

    const order = {
      product_id: product.id,
      quantity,

      customer: {
        full_name: form.get("full_name"),
        email: form.get("email"),
      },

      delivery_address: {
        address_line: form.get("address_line"),
        city: form.get("city"),
        postcode: form.get("postcode"),
      },

      payment: {
        cardholder_name: form.get("cardholder_name"),
        card_number: form.get("card_number"),
        expiry_date: form.get("expiry_date"),
        security_code: form.get("security_code"),
      },
    };

    try {
      const response = await createOrder(order);

      navigate("/confirmation", {
        state: {
          order: response.data,
        },
      });
    } catch (error) {
      setFeedback(getErrorFeedback(error));
      setSubmitting(false);
    }
  }

  return (
    <div className="page checkout-page">
      <h1>Checkout</h1>

      <div className="checkout-summary">
        <img
          src={getImageUrl(product.image_url)}
          alt={product.name}
          className="checkout-image"
        />

        <div>
          <h2>{product.name}</h2>

          <div>Quantity: {quantity}</div>

          <div>
            {product.currency}{" "}
            {(product.price * quantity).toFixed(2)}
          </div>
        </div>
      </div>

      <form onSubmit={handleSubmit}>
        <h2>Customer details</h2>

        <label htmlFor="full-name">
          Full name
        </label>
        <input
          id="full-name"
          name="full_name"
          type="text"
          required
        />

        <label htmlFor="email">
          Email
        </label>
        <input
          id="email"
          name="email"
          type="email"
          required
        />

        <h2>Delivery address</h2>

        <label htmlFor="address">
          Address
        </label>
        <input
          id="address"
          name="address_line"
          type="text"
          required
        />

        <label htmlFor="city">
          City
        </label>
        <input
          id="city"
          name="city"
          type="text"
          required
        />

        <label htmlFor="postcode">
          Postcode
        </label>
        <input
          id="postcode"
          name="postcode"
          type="text"
          required
        />

        <h2>Payment</h2>

        <label htmlFor="card-name">
          Cardholder name
        </label>
        <input
          id="card-name"
          name="cardholder_name"
          type="text"
          required
        />

        <label htmlFor="card-number">
          Card number
        </label>
        <input
          id="card-number"
          name="card_number"
          type="text"
          required
        />

        <label htmlFor="expiry">
          Expiry date
        </label>
        <input
          id="expiry"
          name="expiry_date"
          type="text"
          placeholder="MM/YY"
          required
        />

        <label htmlFor="security-code">
          Security code
        </label>
        <input
          id="security-code"
          name="security_code"
          type="text"
          required
        />

        {feedback && (
          <div className="error" role="alert">
            <strong>
              There was a problem with your order.
            </strong>

            <ul>
              {feedback.messages.map((message, index) => (
                <li key={index}>
                  {message}
                </li>
              ))}
            </ul>

            {feedback.suggestions.length > 0 && (
              <>
                <div>Suggestions:</div>

                <ul>
                  {feedback.suggestions.map(
                    (suggestion, index) => (
                      <li key={index}>
                        {suggestion}
                      </li>
                    )
                  )}
                </ul>
              </>
            )}
          </div>
        )}

        <button
          type="submit"
          disabled={submitting}
        >
          {submitting
            ? "Placing order..."
            : "Place order"}
        </button>
      </form>
    </div>
  );
}

export default Checkout;
